		//Primitive Data Types:- int,double,float,char,long,boolean  
		
		//Non primitive Data Types:- String, array
		
		
		//Primitive Data Types : cannot use everything only use particular thing
		// 1. Initialization means give variable as well as value
		// 2. Declaration means only giving variable
		
		
		int a=5,b=6;  //Initialization
		int c,d;      //Declaration
		System.out.println("Addition"+(a+b));    //+ Operator is called concat
		System.out.println("Subtraction"+(a-b));
		System.out.println("Multiplication"+(a*b));
		System.out.println("Division"+(a/b));
		
		// int is a data types used for integer values
		// double is data types used for decimal values
		
		double f=4.5,e=5.5;
		System.out.println("Addition is"+(f+e));
		System.out.println("Subtraction is"+(f-e));
		System.out.println("Multiplication is"+(f*e));
		System.out.println("division is"+(f/e));
		
		// Float is data types used for decimal values
		// Mostly used in calculator
		
